#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

using ll = long long;

const ll INF = 1000000000;

ll n;
vector<ll> a(18);
ll answer = INF;

ll compute(ll m, int index);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;

    a[0] = 1;
    for (int i = 1; i < 18; ++i) {
        a[i] = a[i - 1] * 10 + 1;
    }

    cout << compute(n, 17) << "\n";

    return 0;
}

ll compute(ll m, int idx) {
    ll total = (m / a[idx]) * (idx + 1);
    m %= a[idx];
    if (m == 0) return total;
    return total + min((ll)(idx + 1) + compute(a[idx] - m, idx - 1), compute(m, idx - 1));
}
